CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', terms_version text, terms_accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_peakfive_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (new.id,left(coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name',''),120)); RETURN new; END; $$;
REVOKE ALL ON FUNCTION public.create_peakfive_profile() FROM PUBLIC;
CREATE TRIGGER peakfive_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_peakfive_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,left(coalesce(raw_user_meta_data->>'full_name',raw_user_meta_data->>'name',''),120) FROM auth.users ON CONFLICT (id) DO NOTHING;
CREATE TABLE public.saved_scenarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120), description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 2000), inputs jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.saved_scenarios TO authenticated;
GRANT ALL ON public.saved_scenarios TO service_role;
ALTER TABLE public.saved_scenarios ENABLE ROW LEVEL SECURITY;
CREATE POLICY scenarios_read_own ON public.saved_scenarios FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY scenarios_insert_own ON public.saved_scenarios FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.profiles WHERE id=auth.uid() AND terms_accepted_at IS NOT NULL));
CREATE POLICY scenarios_update_own ON public.saved_scenarios FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY scenarios_delete_own ON public.saved_scenarios FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE INDEX saved_scenarios_owner ON public.saved_scenarios(user_id,created_at DESC);
CREATE TABLE public.account_deletion_requests (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, requested_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','processing')));
GRANT SELECT, INSERT ON public.account_deletion_requests TO authenticated;
GRANT ALL ON public.account_deletion_requests TO service_role;
ALTER TABLE public.account_deletion_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY deletion_read_own ON public.account_deletion_requests FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY deletion_request_own ON public.account_deletion_requests FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND status='requested');